namespace RonSijm.FluidHumidifier.Factories.BedrockAgentCore;

public class GatewayFactory(string resourceName = null, Action<Humidifier.BedrockAgentCore.Gateway> factoryAction = null) : ResourceFactory<Humidifier.BedrockAgentCore.Gateway>(resourceName)
{

    internal List<InnerGatewayGatewayInterceptorConfigurationFactory> InterceptorConfigurationsFactories { get; set; } = [];

    internal InnerGatewayGatewayPolicyEngineConfigurationFactory PolicyEngineConfigurationFactory { get; set; }

    internal InnerGatewayGatewayProtocolConfigurationFactory ProtocolConfigurationFactory { get; set; }

    internal InnerGatewayWafConfigurationFactory WafConfigurationFactory { get; set; }

    internal InnerGatewayAuthorizerConfigurationFactory AuthorizerConfigurationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.Gateway Create()
    {
        var gatewayResult = CreateGateway();
        factoryAction?.Invoke(gatewayResult);

        return gatewayResult;
    }

    private Humidifier.BedrockAgentCore.Gateway CreateGateway()
    {
        var gatewayResult = new Humidifier.BedrockAgentCore.Gateway
        {
            GivenName = InputResourceName,
        };

        return gatewayResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.Gateway result)
    {
        base.CreateChildren(result);

        result.InterceptorConfigurations = InterceptorConfigurationsFactories.Any() ? InterceptorConfigurationsFactories.Select(x => x.Build()).ToList() : null;
        result.PolicyEngineConfiguration ??= PolicyEngineConfigurationFactory?.Build();
        result.ProtocolConfiguration ??= ProtocolConfigurationFactory?.Build();
        result.WafConfiguration ??= WafConfigurationFactory?.Build();
        result.AuthorizerConfiguration ??= AuthorizerConfigurationFactory?.Build();
    }

} // End Of Class

